types.declaration:
export interface BrulionCommand {
  id: string
  label: string
  description?: string
  icon?: ExtensionIconName
}

export interface RegisterResult {
  actionId: string
}

export interface EditorSelection {
  anchor: number
  head: number
  text: string
}

export interface EditorSelectionRequest {
  anchor: number
  head: number
}

export interface NoteContent {
  content: string
  lastModified: number | null
}

export type CreateResult =
  | { status: "created" }
  | { status: "exists" }

export type SaveResult =
  | { status: "saved"; lastModified: number }
  | { status: "conflict" }

export type MoveResult =
  | { status: "moved" }
  | { status: "exists" }
  | { status: "missing" }

export interface ActiveNote {
  path: string
}

export interface OpenNoteOptions {
  anchor?: string
}

export type OpenNoteResult =
  | {
      status: "opened" | "already-open"
      path: string
      anchor: string | null
      anchorStatus: AnchorStatus
    }
  | { status: "missing"; path: string; anchor: string | null }
  | { status: "conflict"; path: string }

export interface ResolveLinkOptions {
  from?: string
  kind: LinkKind
}

export type LinkResolution =
  | { status: "resolved"; path: string; anchor: string | null }
  | { status: "missing"; path: string; anchor: string | null }
  | { status: "external"; target: string }
  | { status: "invalid"; target: string }

export interface MessagePart {
  type: "text" | "strong" | "code"
  text: string
}

methods.example:
await api.commands.register(
  { id: "insert-date", label: "Insert date", icon: "sparkles" },
  async () => {
    await api.editor.replaceSelection(new Date().toISOString().slice(0, 10))
  },
)

const current = await api.notes.read("todo")
const result = await api.notes.write(
  "todo",
  current.content + "\n- New item",
  current.lastModified,
)
if (result.status === "conflict") console.warn("Changed externally")
